	rayParams.FilterType = Enum.RaycastFilterType.Exclude
	rayParams.FilterDescendantsInstances = {script.Parent}
	local function getMoveAnimation()
		if RunType == 2 then
			return Crouching and Animations.CrouchWalk or Animations.Run
		elseif RunType == 1 then
			return Crouching and Animations.CrouchWalk or Animations.Walk
		end
		return nil
	end
	local function groundIsClose()
		local root = hum.RootPart
		if not root then return false end
		local vy = root.AssemblyLinearVelocity.Y
		if vy > -2 then return false end
		local standHeight = 3
		if hum.RigType == Enum.HumanoidRigType.R15 then
			standHeight = hum.HipHeight + root.Size.Y / 2
		end
		local reach = standHeight + (-vy * LAND_LEAD) + 0.25
		return workspace:Raycast(root.Position, Vector3.new(0, -reach, 0), rayParams) ~= nil
	end
	local function startLanding()
		landingActive = true
		idling = false
		Speed = 2
		JumpPower = 0
		StopAnimation()
		PlayAnimation(Animations.Land, 0.05)
		addsound(randomsound(Sounds.Land), Hrp, 1)
		task.delay(0.5, function()
			Speed = OriginalSpeed
			landingActive = false
			currentMoveAnim = nil
			lastCrouchState = nil
			task.wait(1.5)
			JumpPower = 60
		end)
	end
	while true do
		task.wait()
		if not Testing then
			hum.WalkSpeed = Speed
			hum.JumpPower = JumpPower
		end
		if Humanoid.Health <= 0 then break end
		if getCool and (getCool("Startup") or getCool("Attacking")) then
			continue
		end
		local currentState = hum:GetState()
		if landingActive then
			continue
		end
		if CJumpAnim then
			if isAirborne then
				local landed =
					currentState == Enum.HumanoidStateType.Landed
					or currentState == Enum.HumanoidStateType.Running
					or currentState == Enum.HumanoidStateType.RunningNoPhysics
					or (
						LAND_LEAD > 0
						and currentState == Enum.HumanoidStateType.Freefall
						and os.clock() - airborneSince > 0.1
						and groundIsClose()
					)
				if landed then
					isAirborne = false
					if not Crouching then
						startLanding()
						continue
					else
						currentMoveAnim = nil
						lastCrouchState = nil
					end
				end
			end
			if currentState == Enum.HumanoidStateType.Freefall or currentState == Enum.HumanoidStateType.Jumping then
				if not isAirborne then
					isAirborne = true
					airborneSince = os.clock()
					idling = false
					if not Crouching then
						StopAnimation()
						PlayAnimation(Animations.Falling, 0.2)
					end
				end
				continue
			end
		else
			isAirborne = false
		end
		if not Mover then continue end
		if hum.MoveDirection == Vector3.new(0, 0, 0) then
			if not idling or lastCrouchState ~= Crouching then
				local changedCrouch = (lastCrouchState ~= nil and lastCrouchState ~= Crouching)
				idling = true
				lastCrouchState = Crouching
				currentMoveAnim = nil
				StopAnimation()
				local fadeTime = changedCrouch and 1 or 0.25
				if Crouching then
					PlayAnimation(Animations.CrouchIdle, fadeTime)
				else
					PlayAnimation(Animations.Idle, fadeTime)
				end
			end
			local check = Crouching and Animations.CrouchIdle or Animations.Idle
			if idling and not check.IsPlaying then
				StopAnimation()
				PlayAnimation(check, 0.25)
			end
		else
			if CanRun then
				local desired = getMoveAnimation()
				if desired and (idling or desired ~= currentMoveAnim or not desired.IsPlaying) then
					local changedCrouch = (lastCrouchState ~= nil and lastCrouchState ~= Crouching)
					idling = false
					lastCrouchState = Crouching
					currentMoveAnim = desired
					StopAnimation()
					local fadeTime = 0.25
					if desired ~= Animations.Run and changedCrouch then
						fadeTime = 1
					end
					PlayAnimation(desired, fadeTime)
				end
			end
		end
	end
end)
