		end)
	elseif goal == "sprint" and not Stunned and not Dead and not getCool("Attacking") and not Crouching then
		if not CanRun then return end
		local on = args.on
		if on then
			OriginalSpeed = SprintSpeed
			Speed = OriginalSpeed
			RunType = 2
		else
			RunType = 1
			OriginalSpeed = WalkSpeed
			Speed = OriginalSpeed
		end
	end
end)
if Footsteps then
	for _, track in pairs(Animations) do
		track.KeyframeReached:Connect(function(kf)
			if kf == "stepwalk" then
				local s = addsound(randomsound(Sounds.Footsteps.Walk), Hrp, 0.4)
			elseif kf == "steprun" then
				local s = addsound(randomsound(Sounds.Footsteps.Run), Hrp, 0.4)
			elseif kf == "stepcrawl" then
				local s = addsound(randomsound(Sounds.Footsteps.Walk), Hrp, 0.2)
			end
		end)
	end
end
end
end
_m["BonS.Animator"]=function()
return function()
local AnimatorModule = {}
local function Contains(Table, Check)
	for Index, Value in next, Table do
		if rawequal(Check, Index) or rawequal(Check, Value) then
			return true
		end
	end
	return false
end
local function Edit(Joint, Change, Duration, Style, Direction)
	Style = Enum.EasingStyle.Linear
	Direction = Enum.EasingDirection.InOut
	local Anim = game:GetService("TweenService"):Create(Joint, TweenInfo.new(Duration, Style, Direction), {CFrame = Change})
	Anim:Play()
	return Anim
end
function AnimatorModule:LoadAnimation(Rig, KeyframeSequence)
	local AnimDefaults = {}
	local Joints = {}
	for i,v in pairs(Rig:GetDescendants())do
		if v:IsA("Bone") then
			AnimDefaults[v.Name] = v.CFrame
			Joints[v.Name] = v
		end
	end
	local Sequence = KeyframeSequence
	assert(Sequence:IsA("KeyframeSequence"), "KeyframeSequence Missing!")
	local Class = {}
	Class.Speed = 1
	Class.KeepLast = 0
	local Keyframes = KeyframeSequence:GetKeyframes()
	table.sort(Keyframes, function(a, b) return a.Time < b.Time end)
	Class.Length = Keyframes[#(Keyframes)].Time
	local Yield = function(Seconds)
		local Time = Seconds * (60 + Class.Length)
		local n = 0
		for i = 1, Time, Class.Speed do
			n += 1
		end
		if n > 0 then
			task.wait(n / 60)
		end
	end
	Class.Stopped = true
	Class.IsPlaying = false
	Class.TimePosition = 0
	Class.Looped = Sequence.Loop
	local Completion = Instance.new("BindableEvent")
	local Reached = Instance.new("BindableEvent")
	Class.Completed = Completion.Event
	Class.KeyframeReached = Reached.Event
	Class["Play"] = function(self, FadeIn, Speed)
		if Speed and Speed < 0 then
			Speed += (Speed*2)
		end
		Class.Speed = Speed or Class.Speed
		Class.Stopped = false
		Class.IsPlaying = true
		task.spawn(function()
			wait(1/60)
			if FadeIn ~= nil then
				Class.TimePosition -= FadeIn
			end
			Class.Completed:Connect(function()
				if Class.Looped ~= false then
					Class.TimePosition = 0
				end
			end)
			repeat game:GetService("RunService").Heartbeat:Wait()
				Class.TimePosition += (1 * Class.Speed) / (60 * Class.Speed)
			until Class.IsPlaying == false or Class.Stopped ~= false
		end)
		task.spawn(function()
			if FadeIn ~= nil then
				task.wait(1/55)
				task.spawn(function()
					local Frames = Keyframes[1]:GetDescendants()
					for i = 1, #(Frames) do
						local Pose = Frames[i]
						if Contains(Joints, Pose.Name) then
							task.spawn(function()
								for i = 1, 2 do
									Edit(Joints[Pose.Name], AnimDefaults[Pose.Name] * Pose.CFrame, FadeIn, Pose.EasingStyle, Pose.EasingDirection)
									task.wait()
								end
							end)
						end
					end
				end)
				Yield(FadeIn)
			end
			repeat
				for K = 1, #(Keyframes) do
					local K0, K1, K2 = Keyframes[K-1], Keyframes[K], Keyframes[K+1]
					if Class.Stopped ~= true then
						if K0 ~= nil then
							Yield(K1.Time - K0.Time)
						end
						task.spawn(function()
							for i = 1, #(K1:GetDescendants()) do
								local Pose = K1:GetDescendants()[i]
								if Contains(Joints, Pose.Name) then
									local Duration = K2 ~= nil and (K2.Time - K1.Time) / Class.Speed or 0.5
									Edit(Joints[Pose.Name], AnimDefaults[Pose.Name] * Pose.CFrame, Duration, Pose.EasingStyle, Pose.EasingDirection)
								end
							end
						end)
						if K == #(Keyframes) and Class.KeepLast > 0 then
							Yield(Class.KeepLast)
						end
						Reached:Fire(K1.Name)
					else
						break
					end
				end
				Completion:Fire()
			until Class.Looped ~= true or Class.Stopped ~= false
			Class.IsPlaying = false
		end)
	end
	Class["Stop"] = function()
		Class.Stopped = true
	end
	Class["AdjustSpeed"] = function(self, Speed)
		if Speed < 0 then
			Speed += (Speed*2)
		end
		Class.Speed = Speed or Class.Speed
	end
	return Class
end
return AnimatorModule
end
end
_m["BonS.Follow"]=function()
return function()
local RunService = game:GetService("RunService")
local direction = script:WaitForChild("Direction").Value
local bodyVelocity = script:WaitForChild("BodyVelocity").Value
local character = script:WaitForChild("Character").Value
local Hrp = character:FindFirstChild("HumanoidRootPart")
local useCamera = script:WaitForChild("UseCamera").Value
local Speed = script.Count.Value
local ignore = {}
local function reset()
	for i,v in pairs(workspace:GetChildren()) do
		if v:IsA("Model") and v:FindFirstChildWhichIsA("Humanoid") and not table.find(ignore, v) then
			table.insert(ignore, v)
		end
	end
end
local Fired = false
reset()
spawn(function()
	while true do
		task.wait(0.5)
		reset()
	end
end)
local function wallcheck()
	local p = RaycastParams.new()
	p.FilterType = Enum.RaycastFilterType.Exclude
	p.FilterDescendantsInstances = ignore
	local ray = workspace:Raycast(Hrp.Position, Hrp.CFrame.LookVector.Unit * 6.5, p)
	if ray and ray.Instance and ray.Instance.CanCollide ~= false then
		return true, ray.Position, ray.Normal
	else
		return false
	end
end
if script.Up.Value > 0 then
	bodyVelocity.MaxForce = Vector3.new(math.huge, math.huge, math.huge)
	task.delay(0.2, function()
		bodyVelocity.MaxForce = Vector3.new(math.huge, 0, math.huge)
	end)
end
local Run = RunService.RenderStepped:Connect(function()
	if direction ~= nil then
		if direction == "Left" then
			if wallcheck() then
				bodyVelocity.Velocity = Vector3.new(0, 0, 0)
				return
			end
			if useCamera then
				local CamVector = workspace.CurrentCamera.CFrame.LookVector
				local Pos = Hrp.Position
				Hrp.CFrame = CFrame.new(Pos,Pos+Vector3.new(CamVector.X,0,CamVector.Z))
				bodyVelocity.Velocity = CFrame.new(Pos,Pos + Vector3.new(CamVector.X,0,CamVector.Z)).RightVector*-Speed.Value
			else
				bodyVelocity.Velocity = Hrp.CFrame.RightVector * -Speed.Value
			end
		elseif direction == "Right" then
			if wallcheck() then
				bodyVelocity.Velocity = Vector3.new(0, 0, 0)
				return
			end
			if useCamera then
				local CamVector = workspace.CurrentCamera.CFrame.LookVector
				local Pos = Hrp.Position
				Hrp.CFrame = CFrame.new(Pos,Pos+Vector3.new(CamVector.X,0,CamVector.Z))
				bodyVelocity.Velocity = CFrame.new(Pos,Pos + Vector3.new(CamVector.X,0,CamVector.Z)).RightVector*Speed.Value
			else
				bodyVelocity.Velocity = Hrp.CFrame.RightVector * Speed.Value
			end
		elseif direction == "Back" then
			if wallcheck() then
				bodyVelocity.Velocity = Vector3.new(0, 0, 0)
				return
			end
			if useCamera then
				local CamVector = workspace.CurrentCamera.CFrame.LookVector
				local Pos = Hrp.Position
				Hrp.CFrame = CFrame.new(Pos,Pos+Vector3.new(CamVector.X,0,CamVector.Z))
				bodyVelocity.Velocity = CFrame.new(Pos,Pos + Vector3.new(CamVector.X,0,CamVector.Z)).LookVector*-Speed.Value
			else
				bodyVelocity.Velocity = Hrp.CFrame.LookVector * -Speed.Value + Vector3.new(0, script.Up.Value, 0)
			end
		elseif direction == "Front" then
			local variable, pos, normal = wallcheck()
			if variable then
				bodyVelocity.Velocity = Vector3.new(0, 0, 0)
				if not Fired then
					Fired = true
					_FS(script.Remote.Value, pos, normal)
				end
				return
			end
			if useCamera then
				local CamVector = workspace.CurrentCamera.CFrame.LookVector
				local Pos = Hrp.Position
				Hrp.CFrame = CFrame.new(Pos,Pos+Vector3.new(CamVector.X,0,CamVector.Z))
				bodyVelocity.Velocity = CFrame.new(Pos,Pos + Vector3.new(CamVector.X,0,CamVector.Z)).LookVector*Speed.Value
			else
				bodyVelocity.Velocity = Hrp.CFrame.LookVector * Speed.Value + Vector3.new(0, script.Up.Value, 0)
			end
		end
	else
		if useCamera then
			local CamVector = workspace.CurrentCamera.CFrame.LookVector
			local Pos = Hrp.Position
			Hrp.CFrame = CFrame.new(Pos,Pos+Vector3.new(CamVector.X,0,CamVector.Z))
			bodyVelocity.Velocity = CFrame.new(Pos,Pos + Vector3.new(CamVector.X,0,CamVector.Z)).LookVector*Speed.Value
		else
			bodyVelocity.Velocity = Hrp.CFrame.LookVector * Speed.Value
		end
	end
end)
script.Disconnected.Changed:Connect(function(value)
	if script.Disconnected.Value == true then
		Run:Disconnect()
	end
end)
end
end
