_m["BonS.VictimAnims.R6.MainModule"]=function()
return function()
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local RawData = {}
local HOLD_TIME = 5
for _, child in ipairs(script:GetChildren()) do
	if child:IsA("ModuleScript") and child.Name:sub(1, 10) == "DataChunk_" then
		local ok, chunkData = pcall(_RQ, child)
		if ok and type(chunkData) == "table" then
			for t, joints in pairs(chunkData) do
				RawData[t] = joints
			end
		end
	end
end
local Keyframes = {}
local Duration = 0
for rawTime, joints in pairs(RawData) do
	local t = tonumber(rawTime)
	if t then
		t = math.floor(t * 10000 + 0.5) / 10000
		if t > Duration then Duration = t end
		Keyframes[t] = Keyframes[t] or {}
		for partName, poseInfo in pairs(joints) do
			if type(poseInfo) == "table" and poseInfo.CF and #poseInfo.CF == 12 then
				Keyframes[t][partName] = {
					CFrame = CFrame.new(unpack(poseInfo.CF)),
					Style = Enum.EasingStyle[poseInfo.Style] or Enum.EasingStyle.Linear,
					Dir = Enum.EasingDirection[poseInfo.Dir] or Enum.EasingDirection.Out
				}
			end
		end
	end
end
local times = {}
for t in pairs(Keyframes) do table.insert(times, t) end
table.sort(times)
return function(target)
	local victimChar = typeof(target) == "Instance" and target:IsA("Model") and target
	if not victimChar and type(target) == "string" then
		victimChar = workspace:FindFirstChild(target)
		if not victimChar then
			for _, obj in ipairs(workspace:GetDescendants()) do
				if obj:IsA("Model") and obj.Name == target and obj:FindFirstChildOfClass("Humanoid") then
					victimChar = obj
					break
				end
			end
		end
	end
	if not victimChar then
		return
	end
	local hum = victimChar:FindFirstChildOfClass("Humanoid")
	local rootPart = victimChar:FindFirstChild("HumanoidRootPart")
	if not hum or not rootPart then
		return
	end
	local motorMap = {}
	local originalC0s = {}
	local originalAnchored = {}
	local r6PartToMotorName = {
		["Left Arm"] = "Left Shoulder",
		["Right Arm"] = "Right Shoulder",
		["Left Leg"] = "Left Hip",
		["Right Leg"] = "Right Hip",
		["Head"] = "Neck",
		["Torso"] = "RootJoint"
	}
	for _, desc in ipairs(victimChar:GetDescendants()) do
		if desc:IsA("Motor6D") then
			originalC0s[desc] = desc.C0
			motorMap[desc.Name] = desc
			local ok, p2 = pcall(function() return desc.Part2 end)
			if ok and p2 then
				motorMap[p2.Name] = desc
			end
		elseif desc:IsA("BasePart") then
			originalAnchored[desc] = desc.Anchored
		end
	end
	for partName, motorName in pairs(r6PartToMotorName) do
		if not motorMap[partName] and motorMap[motorName] then
			motorMap[partName] = motorMap[motorName]
		end
	end
	hum:SetStateEnabled(Enum.HumanoidStateType.Running, false)
	hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false)
	hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
	for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
		track:Stop(0)
	end
	local animator = hum:FindFirstChildOfClass("Animator")
	if animator then
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			track:Stop(0)
		end
	end
	local startTime = os.clock()
	local totalRuntime = Duration + HOLD_TIME
	local connection
	connection = RunService.Stepped:Connect(function()
		local elapsed = os.clock() - startTime
		if elapsed >= totalRuntime then
			for part, anchored in pairs(originalAnchored) do
				if part.Parent then
					part.Anchored = anchored
				end
			end
			hum.PlatformStand = false
			for motor, c0 in pairs(originalC0s) do
				if motor.Parent then
					motor.C0 = c0
				end
			end
			hum:SetStateEnabled(Enum.HumanoidStateType.Running, true)
			hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
			hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
			connection:Disconnect()
			return
		end
		if elapsed >= Duration then
			for _, desc in ipairs(victimChar:GetDescendants()) do
				if desc:IsA("BasePart") then
					desc.Anchored = true
					desc.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
					desc.AssemblyAngularVelocity = Vector3.new(0, 0, 0)
				end
			end
			hum.PlatformStand = true
			return
		end
		rootPart.Anchored = true
		hum.PlatformStand = true
		local animTime = elapsed
		local low, high = 1, #times
		local i1, i2 = 1, 1
		while low <= high do
			local mid = math.floor((low + high) / 2)
			if animTime >= times[mid] and (mid == #times or animTime < times[mid + 1]) then
				i1 = mid
				i2 = math.min(mid + 1, #times)
				break
			elseif animTime < times[mid] then
				high = mid - 1
			else
				low = mid + 1
			end
		end
		local t1, t2 = times[i1], times[i2]
		local rawAlpha = (t2 == t1) and 0 or ((animTime - t1) / (t2 - t1))
		local kf1 = Keyframes[t1] or {}
		local kf2 = Keyframes[t2] or kf1
		for partName, pose1 in pairs(kf1) do
			local motor = motorMap[partName]
			if motor and originalC0s[motor] then
				local pose2 = kf2[partName] or pose1
				local smoothedAlpha = TweenService:GetValue(rawAlpha, pose2.Style, pose2.Dir)
				local targetCF = pose1.CFrame:Lerp(pose2.CFrame, smoothedAlpha)
				motor.C0 = originalC0s[motor] * targetCF
			end
		end
	end)
end
end
end
