_m["BonS.VictimAnims.R15.MainModule"]=function()
return function()
local TweenService = game:GetService("TweenService")
local RunService = game:GetService("RunService")
local HOLD_TIME = 5
local USE_R6_ALIASES = false
local R6_ALIASES = {
	["Left Arm"] = "LeftShoulder",
	["Right Arm"] = "RightShoulder",
	["Left Leg"] = "LeftHip",
	["Right Leg"] = "RightHip",
	["Head"] = "Neck",
	["Torso"] = "Root",
}
local RawData = {}
for _, child in ipairs(script:GetChildren()) do
	if child:IsA("ModuleScript") and child.Name:sub(1, 10) == "DataChunk_" then
		local ok, chunkData = pcall(_RQ, child)
		if ok and type(chunkData) == "table" then
			for t, joints in pairs(chunkData) do
				RawData[t] = joints
			end
		end
	end
end
local Keyframes = {}
local Duration = 0
for rawTime, joints in pairs(RawData) do
	local t = tonumber(rawTime)
	if t then
		t = math.floor(t * 10000 + 0.5) / 10000
		if t > Duration then Duration = t end
		Keyframes[t] = Keyframes[t] or {}
		for partName, poseInfo in pairs(joints) do
			if type(poseInfo) == "table" and poseInfo.CF and #poseInfo.CF == 12 then
				Keyframes[t][partName] = {
					CFrame = CFrame.new(unpack(poseInfo.CF)),
					Style = Enum.EasingStyle[poseInfo.Style] or Enum.EasingStyle.Linear,
					Dir = Enum.EasingDirection[poseInfo.Dir] or Enum.EasingDirection.Out,
				}
			end
		end
	end
end
local times = {}
for t in pairs(Keyframes) do table.insert(times, t) end
table.sort(times)
local function buildJointMap(char)
	local map = {}
	local originals = {}
	local function register(name, record)
		if name and not map[name] then
			map[name] = record
		end
	end
	for _, d in ipairs(char:GetDescendants()) do
		local record
		local childPart
		if d:IsA("Motor6D") then
			childPart = d.Part1
			record = {
				get = function() return d.C0 end,
				set = function(cf) d.C0 = cf end,
				alive = function() return d.Parent ~= nil end,
			}
		elseif d:IsA("AnimationConstraint") and d.Attachment0 then
			local a0 = d.Attachment0
			childPart = d.Attachment1 and d.Attachment1.Parent
			record = {
				get = function() return a0.CFrame end,
				set = function(cf) a0.CFrame = cf end,
				alive = function() return a0.Parent ~= nil end,
			}
		end
		if record then
			record.original = record.get()
			originals[record] = true
			register(d.Name, record)
			if childPart then register(childPart.Name, record) end
		end
	end
	if USE_R6_ALIASES then
		for r6Name, jointName in pairs(R6_ALIASES) do
			if not map[r6Name] and map[jointName] then
				map[r6Name] = map[jointName]
			end
		end
	end
	return map, originals
end
local activeRuns = setmetatable({}, { __mode = "k" })
return function(target)
	local victimChar = typeof(target) == "Instance" and target:IsA("Model") and target
	if not victimChar and type(target) == "string" then
		victimChar = workspace:FindFirstChild(target)
		if not victimChar then
			for _, obj in ipairs(workspace:GetDescendants()) do
				if obj:IsA("Model") and obj.Name == target and obj:FindFirstChildOfClass("Humanoid") then
					victimChar = obj
					break
				end
			end
		end
	end
	if not victimChar then return end
	local hum = victimChar:FindFirstChildOfClass("Humanoid")
	local rootPart = victimChar:FindFirstChild("HumanoidRootPart")
	if not hum or not rootPart then return end
	if activeRuns[victimChar] then
		activeRuns[victimChar]()
	end
	local jointMap, allJoints = buildJointMap(victimChar)
	local originalAnchored = {}
	for _, desc in ipairs(victimChar:GetDescendants()) do
		if desc:IsA("BasePart") then
			originalAnchored[desc] = desc.Anchored
		end
	end
	hum:SetStateEnabled(Enum.HumanoidStateType.Running, false)
	hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, false)
	hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
	for _, track in ipairs(hum:GetPlayingAnimationTracks()) do
		track:Stop(0)
	end
	local animator = hum:FindFirstChildOfClass("Animator")
	if animator then
		for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
			track:Stop(0)
		end
	end
	local startTime = os.clock()
	local totalRuntime = Duration + HOLD_TIME
	local frozen = false
	local limbsFreed = false
	local connection
	local finished = false
	local function finish()
		if finished then return end
		finished = true
		if connection then connection:Disconnect() end
		if activeRuns[victimChar] then activeRuns[victimChar] = nil end
		for part, anchored in pairs(originalAnchored) do
			if part.Parent then
				part.Anchored = anchored
				part.AssemblyLinearVelocity = Vector3.zero
				part.AssemblyAngularVelocity = Vector3.zero
			end
		end
		hum.PlatformStand = false
		for joint in pairs(allJoints) do
			if joint.alive() then joint.set(joint.original) end
		end
		hum:SetStateEnabled(Enum.HumanoidStateType.Running, true)
		hum:SetStateEnabled(Enum.HumanoidStateType.Jumping, true)
		hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
	end
	activeRuns[victimChar] = finish
	connection = RunService.Heartbeat:Connect(function()
		local elapsed = os.clock() - startTime
		if not victimChar.Parent or not hum.Parent then
			finish()
			return
		end
		if elapsed >= totalRuntime then
			finish()
			return
		end
		if elapsed >= Duration then
			if not frozen then
				frozen = true
				for _, desc in ipairs(victimChar:GetDescendants()) do
					if desc:IsA("BasePart") then
						desc.Anchored = true
						desc.AssemblyLinearVelocity = Vector3.zero
						desc.AssemblyAngularVelocity = Vector3.zero
					end
				end
				hum.PlatformStand = true
			end
			return
		end
		if not limbsFreed then
			limbsFreed = true
			for part in pairs(originalAnchored) do
				if part ~= rootPart and part.Parent then
					part.Anchored = false
				end
			end
		end
		rootPart.Anchored = true
		hum.PlatformStand = true
		if #times == 0 then return end
		local i1 = 1
		for i = 1, #times do
			if times[i] <= elapsed then i1 = i else break end
		end
		local i2 = math.min(i1 + 1, #times)
		local t1, t2 = times[i1], times[i2]
		local rawAlpha = (t2 == t1) and 0 or math.clamp((elapsed - t1) / (t2 - t1), 0, 1)
		local kf1 = Keyframes[t1] or {}
		local kf2 = Keyframes[t2] or kf1
		for name, pose1 in pairs(kf1) do
			local joint = jointMap[name]
			if joint then
				local pose2 = kf2[name] or pose1
				local alpha = TweenService:GetValue(rawAlpha, pose2.Style, pose2.Dir)
				joint.set(joint.original * pose1.CFrame:Lerp(pose2.CFrame, alpha))
			end
		end
	end)
end
end
end
