_m["TransparencyFix"]=function()
return function()
local RunService = game:GetService("RunService")
local player = game.Players.LocalPlayer
local character = player.Character or player.CharacterAdded:Wait()
local targetNames = {
	["WitheredBon_endo"] = true,
	["WitheredBon_endo.001"] = true,
	["WitheredBon_endo.003"] = true,
	["WitheredBon_endo.004"] = true,
	["WitheredBon_endo.005"] = true,
	["WitheredBon_suit.001"] = true,
	["WitheredBon_suit.003"] = true,
	["WitheredBon_suit.004"] = true,
	["WitheredBon_suit.005"] = true,
	["WitheredBon_suit.006"] = true,
	["WitheredBon_suitendo"] = true,
	["hart_ZBrush_defualt_group"] = true
}
RunService.RenderStepped:Connect(function()
	for _, part in pairs(character:GetDescendants()) do
		if part:IsA("BasePart") and targetNames[part.Name] then
			part.LocalTransparencyModifier = 0
		end
	end
end)
end
end
_m["KillCamera.CamScript"]=function()
return function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local Rat = script.Parent.Parent
local player = Players.LocalPlayer
local camera = workspace.CurrentCamera
local event = script.Parent:WaitForChild("CameraEvent")
local renderConnection = nil
local deathConnection = nil
local hiddenParts = {}
local targetPart = nil
local CameraRat = false
local function muteDeathSound(character)
	local hrp = character:WaitForChild("HumanoidRootPart", 5)
	if hrp then
		local diedSound = hrp:WaitForChild("Died", 5)
		if diedSound and diedSound:IsA("Sound") then
			diedSound.Volume = 0
		end
	end
end
player.CharacterAdded:Connect(muteDeathSound)
if player.Character then
	task.spawn(muteDeathSound, player.Character)
end
local function setAvatarVisible(visible)
	local character = player.Character
	if not character then return end
	if not visible then
		for _, part in ipairs(character:GetDescendants()) do
			local isAccessory = part:FindFirstAncestorOfClass("Accessory") or part:FindFirstAncestorOfClass("Accoutrement")
			local isHeadPart = (part.Name == "Head" or part.Parent.Name == "Head")
			if isAccessory or isHeadPart then
				if part:IsA("BasePart") or part:IsA("Decal") then
					part.LocalTransparencyModifier = 1
					table.insert(hiddenParts, part)
				end
			elseif part:IsA("BasePart") or part:IsA("Decal") then
				part.LocalTransparencyModifier = 0
				table.insert(hiddenParts, part)
			end
		end
	else
		for _, part in ipairs(hiddenParts) do
			if part and part.Parent then
				part.LocalTransparencyModifier = 0
			end
		end
		hiddenParts = {}
	end
end
local function stopCamera()
	if renderConnection then
		renderConnection:Disconnect()
		renderConnection = nil
	end
	if deathConnection then
		deathConnection:Disconnect()
		deathConnection = nil
	end
	local character = player.Character
	local humanoid = character and character:FindFirstChildOfClass("Humanoid")
	if humanoid then
		humanoid.AutoRotate = true
		camera.CameraSubject = humanoid
	end
	camera.CameraType = Enum.CameraType.Custom
	setAvatarVisible(true)
	CameraRat = false
end
Rat.AncestryChanged:Connect(function()
	if not Rat:IsDescendantOf(workspace) then
		stopCamera()
	end
end)
script.Destroying:Connect(stopCamera)
local function startCamera(mode)
	local character = player.Character
	if not character then return end
	local humanoid = character:FindFirstChildOfClass("Humanoid")
	if mode == "Rat" then
		local dist = (camera.Focus.Position - camera.CFrame.Position).Magnitude
		if dist > 0.6 then
			return
		end
		targetPart = Rat:WaitForChild("Head")
		CameraRat = true
	else
		targetPart = character:WaitForChild("Head")
		CameraRat = false
		setAvatarVisible(false)
	end
	if deathConnection then deathConnection:Disconnect() end
	if humanoid then
		humanoid.AutoRotate = false
		deathConnection = humanoid.Died:Connect(function()
			task.delay(4, stopCamera)
		end)
	end
	camera.CameraType = Enum.CameraType.Scriptable
	local tweenInfo = TweenInfo.new(0.25, Enum.EasingStyle.Quart, Enum.EasingDirection.Out)
	if renderConnection then renderConnection:Disconnect() end
	local isZooming = true
	local firstFrame = true
	renderConnection = RunService.RenderStepped:Connect(function(dt)
		if not targetPart then return end
		if CameraRat then
			local currentPos = targetPart.CFrame.Position
			local pitchOffset = math.rad(0)
			local yawOffset = math.rad(180)
			local targetRotation = targetPart.CFrame.Rotation * CFrame.Angles(pitchOffset, yawOffset, 0)
			local finalCF = CFrame.new(currentPos) * targetRotation
			camera.CFrame = camera.CFrame:Lerp(finalCF, 1 - math.exp(-10 * dt))
		else
			local finalCF = targetPart.CFrame
			if firstFrame then
				camera.CFrame = finalCF
				firstFrame = false
			else
				if isZooming then
					TweenService:Create(camera, tweenInfo, {CFrame = finalCF}):Play()
				else
					camera.CFrame = finalCF
				end
			end
		end
	end)
	task.delay(0.5, function()
		isZooming = false
	end)
end
_OC(event):Connect(function(command)
	if command == "CameraStart" then
		startCamera("Victim")
	elseif command == "RatCameraStart" then
		startCamera("Rat")
	elseif command == "CameraEnd" or command == "RatCameraEnd" then
		stopCamera()
	end
end)
end
end
_m["KillCamera.VictimEffects"]=function()
return function()
local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local Lighting = game:GetService("Lighting")
local Debris = game:GetService("Debris")
local RunService = game:GetService("RunService")
local model = script.Parent
local player = Players.LocalPlayer
local BLOOD1_TRANSPARENCY = 0.2
local BLOOD2_HOLD = 0.1
local BLOOD2_FADE = 0.1
local BLOOD2_ON = {
	stabin = true,
	heartgrab = true,
	heartcrush = true,
}
local PULSE_REST = 1.14
local PULSE_AMOUNT = 0.05
local BEAT_GAP = 0.25
local BEAT_PAUSE = 1
local BEAT_ATTACK = 0.020
local BEAT_FALL = 25
local BEAT2_STRENGTH = 0.8
local PULSE_ROTATION = 1.5
local DESAT_ON = {
	stabin = true,
	heartgrab = true,
}
local RED_ON = {
	heartbeat = true,
}
local CRUSH_ON = {
	heartcrush = true,
}
local GROUND_ON = {
	hitground = true,
}
local FADEBLACK_ON = {
	fadeblackstart = true,
}
local DESAT = {
	start = { Saturation = -1 },
	finish = { Saturation = 0 },
	time = 1,
}
local RED_FLASH = {
	start = { Brightness = 0.1, TintColor = Color3.fromRGB(255, 170, 170) },
	finish = { Brightness = 0, TintColor = Color3.new(1, 1, 1) },
	time = 0.3,
}
local CRUSH_RED = {
	start = {
		TintColor = Color3.fromRGB(255, 120, 120),
		Saturation = 0.1,
		Contrast = 0.15,
	},
	finish = {
		TintColor = Color3.new(1, 1, 1),
		Saturation = 0,
		Contrast = 0,
	},
	time = 1,
}
local KILLER_RED_TIME = 2
local GROUND_IN = 0.15
local GROUND_HOLD = 0
local GROUND_OUT = 0.15
local VIGNETTE_TIME = 4
local BLACK_DELAY = 0
local BLACK_FADE = 4
local BLACK_HOLD = 3
local BLUR_MAX = 56
local BLUR_TIME = 3
local bloodTemplate1 = script:WaitForChild("Blood1", 10)
local bloodTemplate2 = script:WaitForChild("Blood2", 10)
local vignetteTemplate = script:WaitForChild("Vignette", 10)
if not bloodTemplate1 or not bloodTemplate2 then
	warn("[KillEffects] Put Blood1 and Blood2 inside the KillEffects script")
end
if not vignetteTemplate then
	warn("[KillEffects] Put Vignette inside the KillEffects script")
end
local active = false
local session = 0
local gui, black, blurFx
local blood1, blood2, vig
local blood1On = false
local pulses = {}
local pulseConn
local function muteDeathSound()
	task.spawn(function()
		local character = player.Character
		if not character then return end
		local root = character:WaitForChild("HumanoidRootPart", 2)
		if not root then return end
		local diedSound = root:WaitForChild("Died", 2)
		if diedSound and diedSound:IsA("Sound") then
			diedSound.Volume = 0
		end
	end)
end
local function tween(obj, time, props, style, direction)
	local info = TweenInfo.new(
		time,
		style or Enum.EasingStyle.Quad,
		direction or Enum.EasingDirection.Out
	)
	local newTween = TweenService:Create(obj, info, props)
	newTween:Play()
	return newTween
end
local function makeOverlay(template, centered)
	if not template then return nil end
	local obj, prop
	if template:IsA("Decal") or template:IsA("Texture") then
		obj = Instance.new("ImageLabel")
		obj.Image = template.Texture
		obj.BackgroundTransparency = 1
		obj.ScaleType = Enum.ScaleType.Stretch
		prop = "ImageTransparency"
	else
		obj = template:Clone()
		if obj:IsA("CanvasGroup") then
			prop = "GroupTransparency"
		elseif obj:IsA("ImageLabel") or obj:IsA("ImageButton") then
			prop = "ImageTransparency"
		else
			prop = "BackgroundTransparency"
		end
	end
	if centered then
		obj.AnchorPoint = Vector2.new(0.5, 0.5)
		obj.Position = UDim2.fromScale(0.5, 0.5)
		obj.Size = UDim2.fromScale(PULSE_REST, PULSE_REST)
		obj.Rotation = 0
	else
		obj.AnchorPoint = Vector2.zero
		obj.Position = UDim2.fromScale(0, 0)
		obj.Size = UDim2.fromScale(1, 1)
	end
	obj.Visible = false
	obj[prop] = 1
	obj.Parent = gui
	return { obj = obj, prop = prop, token = 0 }
end
local function clearPulses()
	for fx in pairs(pulses) do
		fx:Destroy()
	end
	pulses = {}
end
local function teardown()
	if not active then return end
	active = false
	session += 1
	if pulseConn then
		pulseConn:Disconnect()
		pulseConn = nil
	end
	for _, overlay in ipairs({ blood1, blood2 }) do
		if overlay then
			overlay.obj.Rotation = 0
			overlay.obj.Size = UDim2.fromScale(PULSE_REST, PULSE_REST)
		end
	end
	clearPulses()
	if blurFx then blurFx:Destroy() end
	if gui then gui:Destroy() end
	gui, black, blurFx = nil, nil, nil
	blood1, blood2, vig = nil, nil, nil
	blood1On = false
end
local function setup()
	if active then return end
	if not model:IsDescendantOf(workspace) then return end
	local playerGui = player:FindFirstChildOfClass("PlayerGui") or player:WaitForChild("PlayerGui", 5)
	if not playerGui then return end
	local oldGui = playerGui:FindFirstChild("KillEffects")
	if oldGui then oldGui:Destroy() end
	for _, parent in ipairs({ Lighting, workspace.CurrentCamera }) do
		if parent then
			for _, child in ipairs(parent:GetChildren()) do
				if child.Name == "KillCC" or child.Name == "KillBlur" then
					child:Destroy()
				end
			end
		end
	end
	active = true
	session += 1
	blood1On = false
	gui = Instance.new("ScreenGui")
	gui.Name = "KillEffects"
	gui.ResetOnSpawn = false
	gui.IgnoreGuiInset = true
	gui.DisplayOrder = 50
	gui.Parent = playerGui
	blood1 = makeOverlay(bloodTemplate1, true)
	blood2 = makeOverlay(bloodTemplate2, true)
	vig = makeOverlay(vignetteTemplate, false)
	black = Instance.new("Frame")
	black.Name = "Black"
	black.Size = UDim2.fromScale(1, 1)
	black.BackgroundColor3 = Color3.new(0, 0, 0)
	black.BackgroundTransparency = 1
	black.BorderSizePixel = 0
	black.Visible = false
	black.Parent = gui
	local startTime = os.clock()
	local cycleLength = BEAT_GAP + BEAT_PAUSE
	local function beatValue(x, strength)
		if x < 0 then return 0 end
		local attack = math.min(x / BEAT_ATTACK, 1)
		return attack * math.exp(-x * BEAT_FALL) * strength
	end
	local lastCycle = -1
	local rot1, rot2 = 0, 0
	pulseConn = RunService.RenderStepped:Connect(function()
		local elapsed = os.clock() - startTime
		local cycleIndex = math.floor(elapsed / cycleLength)
		local t = elapsed % cycleLength
		if cycleIndex ~= lastCycle then
			lastCycle = cycleIndex
			rot1 = (math.random() * 2 - 1) * PULSE_ROTATION
			rot2 = (math.random() * 2 - 1) * PULSE_ROTATION
		end
		local beat1 = beatValue(t, 1)
		local beat2 = beatValue(t - BEAT_GAP, BEAT2_STRENGTH)
		local wave = math.max(beat1, beat2)
		local rotation = rot1 * beat1 + rot2 * beat2
		if wave < 0.001 then
			rotation = 0
		end
		local size = PULSE_REST - wave * PULSE_AMOUNT
		local newSize = UDim2.fromScale(size, size)
		if blood1 then
			blood1.obj.Size = newSize
			blood1.obj.Rotation = rotation
		end
		if blood2 then
			blood2.obj.Size = newSize
			blood2.obj.Rotation = rotation
		end
	end)
end
local function fadeOverlay(overlay, time)
	if not overlay then return end
	overlay.token += 1
	local myToken, mySession = overlay.token, session
	local fade = tween(overlay.obj, time, { [overlay.prop] = 1 })
	fade.Completed:Connect(function()
		if overlay.token == myToken and session == mySession then
			overlay.obj.Visible = false
		end
	end)
end
local function showBlood1()
	if blood1On or not blood1 then return end
	blood1On = true
	blood1.token += 1
	blood1.obj.Visible = true
	blood1.obj[blood1.prop] = BLOOD1_TRANSPARENCY
end
local function hitBlood2()
	local overlay = blood2
	if not overlay then return end
	overlay.token += 1
	local myToken, mySession = overlay.token, session
	overlay.obj.Visible = true
	overlay.obj[overlay.prop] = 0
	task.delay(BLOOD2_HOLD, function()
		if overlay.token ~= myToken or session ~= mySession then return end
		local fade = tween(overlay.obj, BLOOD2_FADE, { [overlay.prop] = 1 }, Enum.EasingStyle.Linear)
		fade.Completed:Connect(function()
			if overlay.token == myToken and session == mySession then
				overlay.obj.Visible = false
			end
		end)
	end)
end
local function colourPulse(look)
	if not active then return end
	local fx = Instance.new("ColorCorrectionEffect")
	fx.Name = "KillCC"
	for property, value in pairs(look.start) do
		fx[property] = value
	end
	fx.Parent = Lighting
	pulses[fx] = true
	Debris:AddItem(fx, look.time + 1)
	local fade = tween(fx, look.time, look.finish)
	fade.Completed:Connect(function()
		pulses[fx] = nil
		fx:Destroy()
	end)
end
local function killerRedPulse()
	local fx = Instance.new("ColorCorrectionEffect")
	fx.Name = "KillerCC"
	for property, value in pairs(CRUSH_RED.start) do
		fx[property] = value
	end
	fx.Parent = Lighting
	Debris:AddItem(fx, KILLER_RED_TIME + 1)
	local fade = tween(fx, KILLER_RED_TIME, CRUSH_RED.finish)
	fade.Completed:Connect(function()
		fx:Destroy()
	end)
end
local function groundSequence()
	if not active then return end
	local mySession = session
	local fx = Instance.new("ColorCorrectionEffect")
	fx.Name = "KillCC"
	fx.Parent = Lighting
	pulses[fx] = true
	Debris:AddItem(fx, GROUND_IN + GROUND_HOLD + GROUND_OUT + 1)
	tween(fx, GROUND_IN, { Saturation = -0.5 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
	task.delay(GROUND_IN + GROUND_HOLD, function()
		if session ~= mySession or not fx.Parent then return end
		local fadeBack = tween(fx, GROUND_OUT, { Saturation = 0 }, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
		fadeBack.Completed:Connect(function()
			pulses[fx] = nil
			fx:Destroy()
		end)
	end)
	if vig then
		vig.token += 1
		vig.obj.Visible = true
		tween(vig.obj, VIGNETTE_TIME, { [vig.prop] = 0 }, Enum.EasingStyle.Linear)
	end
	task.delay(BLACK_DELAY, function()
		if session ~= mySession or not black then return end
		black.Visible = true
		tween(black, BLACK_FADE, { BackgroundTransparency = 0 }, Enum.EasingStyle.Linear)
	end)
end
local function blurSequence()
	if not active then return end
	if blurFx then blurFx:Destroy() end
	blurFx = Instance.new("BlurEffect")
	blurFx.Name = "KillBlur"
	blurFx.Size = 0
	blurFx.Parent = Lighting
	tween(blurFx, BLUR_TIME, { Size = BLUR_MAX }, Enum.EasingStyle.Linear)
end
local function endEffects()
	if not active then return end
	local mySession = session
	local function fadeEverythingOut()
		fadeOverlay(blood1, 1)
		fadeOverlay(blood2, BLOOD2_FADE)
		fadeOverlay(vig, 1)
		if black then
			tween(black, 1, { BackgroundTransparency = 1 })
		end
		if blurFx then
			tween(blurFx, 1, { Size = 0 })
		end
		task.delay(1.2, function()
			if session == mySession then
				teardown()
			end
		end)
	end
	if black and black.Visible then
		task.delay(BLACK_HOLD, function()
			if session == mySession then
				fadeEverythingOut()
			end
		end)
	else
		fadeEverythingOut()
	end
end
local event = script.Parent:WaitForChild("CameraEvent")
_OC(event):Connect(function(command, keyframe)
	if command == "CameraStart" then
		teardown()
		setup()
	elseif command == "Effect" then
		local hasEffect = DESAT_ON[keyframe]
			or RED_ON[keyframe]
			or CRUSH_ON[keyframe]
			or GROUND_ON[keyframe]
			or FADEBLACK_ON[keyframe]
			or BLOOD2_ON[keyframe]
			or keyframe == "stabin"
		if not hasEffect then return end
		setup()
		if not active then return end
		if keyframe == "stabin" then
			showBlood1()
		end
		if BLOOD2_ON[keyframe] then
			hitBlood2()
		end
		if GROUND_ON[keyframe] then
			groundSequence()
		elseif RED_ON[keyframe] then
			colourPulse(RED_FLASH)
		elseif CRUSH_ON[keyframe] then
			colourPulse(CRUSH_RED)
		elseif DESAT_ON[keyframe] then
			colourPulse(DESAT)
		end
		if FADEBLACK_ON[keyframe] then
			blurSequence()
		end
	elseif command == "KillerEffect" then
		if keyframe == "heartcrush" then
			killerRedPulse()
		end
	elseif command == "CameraEnd" or command == "RatCameraEnd" then
		endEffects()
	end
end)
model.AncestryChanged:Connect(function()
	if not model:IsDescendantOf(workspace) then
		teardown()
	end
end)
player.CharacterAdded:Connect(function()
	teardown()
end)
local function silence(obj)
	if obj:IsA("Sound") and obj.Name == "Died" then
		obj.Volume = 0
		obj:Stop()
	end
end
local function watchCharacter(character)
	local function muteIfMarked()
		if character:GetAttribute("NoDeathSound") then
			for _, obj in ipairs(character:GetDescendants()) do
				silence(obj)
			end
		end
	end
	character:GetAttributeChangedSignal("NoDeathSound"):Connect(muteIfMarked)
	character.DescendantAdded:Connect(function(obj)
		if character:GetAttribute("NoDeathSound") then
			silence(obj)
		end
	end)
	local humanoid = character:WaitForChild("Humanoid", 10)
	if humanoid then
		humanoid.Died:Connect(muteIfMarked)
	end
	muteIfMarked()
end
local function watchPlayer(otherPlayer)
	if otherPlayer.Character then
		watchCharacter(otherPlayer.Character)
	end
	otherPlayer.CharacterAdded:Connect(watchCharacter)
end
for _, p in ipairs(Players:GetPlayers()) do
	watchPlayer(p)
end
Players.PlayerAdded:Connect(watchPlayer)
end
end
_m["HeadMovement.MoveJaw"]=function()
return function()
local RunService = game:GetService("RunService")
local model = script.Parent.Parent
local VOICELINES = {
	["Voiceline1"] = true,
	["Voiceline2"] = true,
	["Voiceline3"] = true,
}
local JAW_AXIS = Vector3.new(1, 0, 0)
local JAW_SIGN = 1
local MAX_OPEN = math.rad(20)
local LOUDNESS_MAX = 250
local NOISE_GATE = 15
local OPEN_SPEED = 25
local CLOSE_SPEED = 14
local LOUD_START = 0.6
local LOUD_LIMIT = 0.85
local humanoidRoot = model:WaitForChild("HumanoidRootPart", 15)
local rootPart = model:WaitForChild("RootPart", 15)
if not humanoidRoot or not rootPart then
	return
end
local jaw
for _, descendant in ipairs(rootPart:GetDescendants()) do
	if descendant:IsA("Bone") and descendant.Name == "Jaw" then
		jaw = descendant
		break
	end
end
if not jaw then
	return
end
local sounds = {}
local function track(obj)
	if obj:IsA("Sound") and VOICELINES[obj.Name] then
		sounds[obj] = true
	end
end
for _, child in ipairs(humanoidRoot:GetChildren()) do
	track(child)
end
humanoidRoot.ChildAdded:Connect(track)
humanoidRoot.ChildRemoved:Connect(function(obj)
	sounds[obj] = nil
end)
local open = 0
local resting = true
local connection
connection = RunService.RenderStepped:Connect(function(dt)
	if not model:IsDescendantOf(workspace) then
		connection:Disconnect()
		return
	end
	local loudness = 0
	for sound in pairs(sounds) do
		if sound.IsPlaying then
			loudness = math.max(loudness, sound.PlaybackLoudness)
		end
	end
	local target = 0
	if loudness > NOISE_GATE then
		target = math.clamp((loudness - NOISE_GATE) / (LOUDNESS_MAX - NOISE_GATE), 0, 1)
		if target > LOUD_START then
			local extra = (target - LOUD_START) / (1 - LOUD_START)
			target = LOUD_START + extra * (LOUD_LIMIT - LOUD_START)
		end
	end
	local speed = target > open and OPEN_SPEED or CLOSE_SPEED
	local alpha = 1 - math.exp(-speed * dt)
	open += (target - open) * alpha
	if open < 0.002 and target == 0 then
		if not resting then
			resting = true
			open = 0
			jaw.Transform = CFrame.identity
		end
		return
	end
	resting = false
	jaw.Transform = CFrame.fromAxisAngle(JAW_AXIS, open * MAX_OPEN * JAW_SIGN)
end)
end
end
_m["HeadMovement.HeadA"]=function()
return function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local model = script.Parent.Parent
local remote = script.Parent:WaitForChild("HeadEvent")
local BONES = {
	{ name = "Neck", weight = 0.4 },
	{ name = "Head", weight = 0.6 },
}
local YAW_AXIS = Vector3.new(0, 1, 0)
local PITCH_AXIS = Vector3.new(1, 0, 0)
local YAW_SIGN = 1
local PITCH_SIGN = -1
local SMOOTHING = 12
local RETURN_SMOOTHING = 3
local LOOK_DELAY = 1
local LOOK_THRESHOLD = 0.5
local FRONT_START = 0.3
local FRONT_FULL = 0.7
local LOOK_START = 0.85
local LOOK_FULL = 0.97
local camera = workspace.CurrentCamera
local rootPart = model:WaitForChild("RootPart", 15)
if not rootPart then
	return
end
local joints = {}
local headBone
for _, boneInfo in ipairs(BONES) do
	local found = false
	for _, descendant in ipairs(rootPart:GetDescendants()) do
		if descendant:IsA("Bone") and descendant.Name == boneInfo.name then
			table.insert(joints, { bone = descendant, weight = boneInfo.weight })
			if boneInfo.name == "Head" then
				headBone = descendant
			end
			found = true
			break
		end
	end
	if not found then
	end
end
if #joints == 0 then return end
local humanoidRoot = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
local function faceViewAmount()
	if not humanoidRoot then return 0 end
	local headPos
	if headBone then
		headPos = headBone.TransformedWorldCFrame.Position
	else
		headPos = humanoidRoot.Position
	end
	local toHead = headPos - camera.CFrame.Position
	if toHead.Magnitude < 0.01 then return 0 end
	toHead = toHead.Unit
	local inFront = (-toHead):Dot(humanoidRoot.CFrame.LookVector)
	local looking = camera.CFrame.LookVector:Dot(toHead)
	local frontAmount = math.clamp((inFront - FRONT_START) / (FRONT_FULL - FRONT_START), 0, 1)
	local lookAmount = math.clamp((looking - LOOK_START) / (LOOK_FULL - LOOK_START), 0, 1)
	local blend = frontAmount * lookAmount
	return blend * blend * (3 - 2 * blend)
end
local yaw, pitch = 0, 0
local lookTimer = 0
local resting = true
local sentFace = false
local connection
connection = RunService.RenderStepped:Connect(function(dt)
	if not model:IsDescendantOf(workspace) then
		connection:Disconnect()
		return
	end
	camera = workspace.CurrentCamera
	local isOwner = Players.LocalPlayer and Players.LocalPlayer.Character == model
	local targetYaw = model:GetAttribute("HeadLookYaw") or 0
	local targetPitch = model:GetAttribute("HeadLookPitch") or 0
	local returning = model:GetAttribute("HeadLookReturning") == true
	local speed = returning and RETURN_SMOOTHING or SMOOTHING
	local alpha = 1 - math.exp(-speed * dt)
	yaw += (targetYaw - yaw) * alpha
	pitch += (targetPitch - pitch) * alpha
	if isOwner then
		local view = faceViewAmount()
		if view > LOOK_THRESHOLD then
			lookTimer += dt
		else
			lookTimer = 0
		end
		local staring = lookTimer >= LOOK_DELAY
		if staring ~= sentFace then
			sentFace = staring
			_FS(remote, "Face", staring)
		end
	end
	local atNeutral = math.abs(yaw) < 0.001 and math.abs(pitch) < 0.001
		and targetYaw == 0 and targetPitch == 0
	if atNeutral then
		if not resting then
			resting = true
			yaw, pitch = 0, 0
			for _, joint in ipairs(joints) do
				joint.bone.Transform = CFrame.identity
			end
		end
		return
	end
	resting = false
	for _, joint in ipairs(joints) do
		joint.bone.Transform = CFrame.fromAxisAngle(YAW_AXIS, yaw * YAW_SIGN * joint.weight)
			* CFrame.fromAxisAngle(PITCH_AXIS, pitch * PITCH_SIGN * joint.weight)
	end
end)
end
end
_m["HeadMovement.HeadS"]=function()
return function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local model = script.Parent.Parent
local humanoid = model:FindFirstChildOfClass("Humanoid")
local remote = script.Parent:WaitForChild("HeadEvent")
local MAX_YAW = math.rad(70)
local MAX_PITCH = math.rad(55)
local MIN_INTERVAL = 0.04
local IDLE_TIME = 20
local LOOK_RADIUS = 10
local LOOK_CHECK_RATE = 0.1
local DISABLE_ATTRIBUTES = {
	"HeadLookDisabled",
}
local humanoidRoot = model:WaitForChild("HumanoidRootPart", 15)
local headPart = model:FindFirstChild("Head")
local function isDisabled()
	for _, name in ipairs(DISABLE_ATTRIBUTES) do
		if model:GetAttribute(name) == true then
			return true
		end
	end
	return false
end
local function findNearbyLook()
	if not humanoidRoot then return nil end
	local origin = (headPart or humanoidRoot).Position
	local bestDistance = LOOK_RADIUS
	local bestPosition
	for _, otherPlayer in ipairs(Players:GetPlayers()) do
		local character = otherPlayer.Character
		if character and character ~= model then
			local otherHumanoid = character:FindFirstChildOfClass("Humanoid")
			local otherHead = character:FindFirstChild("Head")
			if otherHumanoid and otherHumanoid.Health > 0 and otherHead then
				local distance = (otherHead.Position - origin).Magnitude
				if distance < bestDistance then
					bestDistance = distance
					bestPosition = otherHead.Position + Vector3.new(0, 2, 0)
				end
			end
		end
	end
	if not bestPosition then return nil end
	local direction = humanoidRoot.CFrame:VectorToObjectSpace((bestPosition - origin).Unit)
	local yaw = math.atan2(-direction.X, -direction.Z)
	local pitch = math.asin(math.clamp(direction.Y, -1, 1))
	if math.abs(yaw) > MAX_YAW then return nil end
	return math.clamp(pitch, -MAX_PITCH, MAX_PITCH), yaw
end
local wantYaw, wantPitch = 0, 0
local shiftLocked = false
local faceLocked = false
local lastFire = 0
local lastMoveTime = os.clock()
local nearYaw, nearPitch, hasNear = 0, 0, false
local lastLookCheck = 0
_OS(remote):Connect(function(player, pitchOrCommand, yawOrFlag, locked)
	if player.Character ~= model then return end
	if pitchOrCommand == "Face" then
		local nowFace = yawOrFlag == true
		if faceLocked and not nowFace then
			lastMoveTime = os.clock()
		end
		faceLocked = nowFace
		return
	end
	if typeof(pitchOrCommand) ~= "number" or typeof(yawOrFlag) ~= "number" then return end
	if pitchOrCommand ~= pitchOrCommand or yawOrFlag ~= yawOrFlag then return end
	local newLocked = locked == true
	local now = os.clock()
	if newLocked == shiftLocked and now - lastFire < MIN_INTERVAL then return end
	lastFire = now
	lastMoveTime = now
	shiftLocked = newLocked
	wantPitch = math.clamp(pitchOrCommand, -MAX_PITCH, MAX_PITCH)
	wantYaw = math.clamp(yawOrFlag, -MAX_YAW, MAX_YAW)
end)
local connection
connection = RunService.Heartbeat:Connect(function()
	if not model.Parent or (humanoid and humanoid.Health <= 0) then
		connection:Disconnect()
		return
	end
	local now = os.clock()
	if now - lastLookCheck >= LOOK_CHECK_RATE then
		lastLookCheck = now
		local foundPitch, foundYaw = findNearbyLook()
		if foundPitch then
			nearPitch, nearYaw, hasNear = foundPitch, foundYaw, true
		else
			hasNear = false
		end
	end
	local blocked = faceLocked or isDisabled()
	local looking = hasNear and not blocked
	local idle = (now - lastMoveTime) > IDLE_TIME
	local returning = blocked or (not looking and (idle or shiftLocked))
	local outYaw = looking and nearYaw or wantYaw
	local outPitch = looking and nearPitch or wantPitch
	model:SetAttribute("HeadLookReturning", returning)
	model:SetAttribute("HeadLookYaw", returning and 0 or outYaw)
	model:SetAttribute("HeadLookPitch", returning and 0 or outPitch)
end)
end
end
_m["HeadMovement.HeadC"]=function()
return function()
local RunService = game:GetService("RunService")
local model = script.Parent.Parent
local remote = script.Parent:WaitForChild("HeadEvent")
local camera = workspace.CurrentCamera
local gameSettings = UserSettings():GetService("UserGameSettings")
local STRENGTH = 1
local SEND_INTERVAL = 0.06
local SEND_THRESHOLD = math.rad(1)
local lastSent = 0
local sentPitch, sentYaw = 0, 0
local sentLocked = false
local function isShiftLock()
	return gameSettings.RotationType == Enum.RotationType.CameraRelative
end
RunService.RenderStepped:Connect(function()
	if model:GetAttribute("HeadLookDisabled") == true then
		sentPitch, sentYaw = 1e9, 1e9
		return
	end
	local rootPart = model:FindFirstChild("HumanoidRootPart") or model.PrimaryPart
	if not rootPart then return end
	local direction = rootPart.CFrame:VectorToObjectSpace(camera.CFrame.LookVector)
	local yaw = math.atan2(-direction.X, -direction.Z)
	local pitch = math.asin(math.clamp(direction.Y, -1, 1))
	pitch *= STRENGTH
	yaw *= STRENGTH
	local locked = isShiftLock()
	local now = os.clock()
	if locked ~= sentLocked then
		sentLocked = locked
		lastSent = now
		sentPitch, sentYaw = pitch, yaw
		_FS(remote, pitch, yaw, locked)
		return
	end
	if locked then return end
	local timeToSend = now - lastSent >= SEND_INTERVAL
	local moved = math.abs(pitch - sentPitch) > SEND_THRESHOLD
		or math.abs(yaw - sentYaw) > SEND_THRESHOLD
	if timeToSend and moved then
		lastSent = now
		sentPitch, sentYaw = pitch, yaw
		_FS(remote, pitch, yaw, false)
	end
end)
end
end
_m["SoundPreloader"]=function()
return function()
local ContentProvider = game:GetService("ContentProvider")
local model = script.Parent
model:WaitForChild("BonS", 10)
task.wait(3)
local sounds = {}
for _, obj in ipairs(model:GetDescendants()) do
	if obj:IsA("Sound") and obj.SoundId ~= "" then
		table.insert(sounds, obj)
	end
end
ContentProvider:PreloadAsync(sounds, function(assetId, status)
	if status ~= Enum.AssetFetchStatus.Success then
	end
end)
script:Destroy()
end
end
_m["DSRemover"]=function()
return function()
local DEFAULT_SOUNDS = {
	["Running"] = true, ["Walking"] = true, ["Jumping"] = true,
	["Landing"] = true, ["Climbing"] = true, ["FreeFalling"] = true,
	["Died"] = true, ["Splash"] = true, ["Swimming"] = true
}
local Character = script.Parent
local soundScript = Character:FindFirstChild("RbxCharacterSounds")
if soundScript then soundScript:Destroy() end
local hrp = Character:WaitForChild("HumanoidRootPart", 10)
if not hrp then return end
local function isDefault(obj)
	return obj:IsA("Sound") and DEFAULT_SOUNDS[obj.Name]
end
for _, obj in ipairs(hrp:GetChildren()) do
	if isDefault(obj) then obj:Destroy() end
end
hrp.ChildAdded:Connect(function(child)
	if isDefault(child) then child:Destroy() end
end)
end
end
_RQ(_A):Bon(_P.Name)
